opportunityUI <- function(id) {
 ns<-NS(id)
 tagList(tags$h2('Invest in possibilities. Keep the uncertainty.'),tags$p(class='lead','Compare grants, books and other uncertain projects, then turn a considered choice into a work goal.'),
 tags$p(class='hint','Probabilities are your assumptions, not predictions. Enter personal income separately from a total grant budget. Losing can still incur costs; preparing a proposal is distinct from winning it.'),
 fluidRow(column(8,section('Compare your options',checkboxGroupInput(ns('compare'),'Opportunities to compare',NULL),selectInput(ns('sort'),'Compare by',c('Expected economic value per hour','Conservative economic value','Chance of success','Expected cash','Smallest cash loss')),
 tableOutput(ns('comparison')),accordion('Detailed assumptions and goal context',tableOutput(ns('details'))),plotOutput(ns('risk_plot'),height='300px'),uiOutput(ns('tradeoffs')),downloadButton(ns('csv'),'Export comparison CSV')),
 section('Connect the decision to your work',selectInput(ns('selected'),'Opportunity to edit or act on',NULL),actionButton(ns('load'),'Edit selected',class='btn-quiet'),actionButton(ns('new'),'New opportunity',class='btn-quiet'),actionButton(ns('goal'),'Create / open goal',class='btn-primary'),actionButton(ns('delete'),'Delete opportunity',class='btn-danger-soft'),uiOutput(ns('connection')))),
 column(4,section('Opportunity details',textInput(ns('name'),'Name'),selectInput(ns('job'),'Work role',NULL),selectInput(ns('kind'),'Type',c('Grant','Book','Other')),selectInput(ns('status'),'Stage',c('Considering','Pursuing','Submitted','Won','Lost','Withdrawn')),dateInput(ns('deadline'),'Submission / preparation deadline',Sys.Date()+30),numericInput(ns('hours'),'Remaining preparation hours (before task breakdown)',20,min=.25,step=.25),
 fluidRow(column(4,numericInput(ns('low'),'Low chance (%)',10,min=0,max=100)),column(4,numericInput(ns('base'),'Central (%)',20,min=0,max=100)),column(4,numericInput(ns('high'),'High (%)',30,min=0,max=100))),
 numericInput(ns('income_success'),'Your personal income if successful',5000,min=0),numericInput(ns('income_failure'),'Your personal income if unsuccessful',0,min=0),numericInput(ns('cost_upfront'),'Remaining cash cost regardless of outcome',0,min=0),
 accordion('Outcome costs, timing & assumptions',numericInput(ns('cost_success'),'Additional cost if successful',0,min=0),numericInput(ns('cost_failure'),'Additional cost if unsuccessful',0,min=0),numericInput(ns('award_total'),'Total award / team budget (context only)',0,min=0),numericInput(ns('years'),'Years until outcome income and costs',1,min=0,max=100),numericInput(ns('discount'),'Annual discount rate (%)',5,min=0,max=100),numericInput(ns('alt'),'Alternative value of an hour of your time',25,min=0),textInput(ns('group'),'Mutually exclusive / overlapping group (optional)'),textAreaInput(ns('basis'),'Evidence or reasoning behind your chances',rows=2),textAreaInput(ns('notes'),'Notes',rows=2)),
 selectInput(ns('goal_link'),'Link an existing preparation goal (optional)',NULL),actionButton(ns('save'),'Save opportunity',class='btn-primary'),tags$p(class='hint','Once a goal has tasks, their remaining hours replace the preparation forecast; logged time appears in the comparison. Cash costs remain your separate forecast. Review costs after incurring them to avoid counting sunk costs again.')))),
 accordion('How to interpret the comparison',tags$p('Expected cash = chance × discounted successful net proceeds + (1 − chance) × discounted unsuccessful net proceeds − remaining upfront cost. Economic value also subtracts remaining hours × your alternative hourly value. A negative result is valid.'),tags$p('The low/high range changes the success chance only, with the same conditional proceeds. It is an assumption range, not a statistical confidence interval. A book uses a simplified success/unsuccessful scenario; royalties and real outcomes can vary more widely.'),tags$p('Expected cash is discounted to today. Cash loss probability and maximum cash loss use the undiscounted two outcome receipts and costs, not unpaid time. Maximum cash loss is the worse of the two entered outcomes. Break-even chance includes the value of time; values above 100% mean the entered successful outcome does not cover the economic cost. A threshold is not applicable when success pays no more than failure.'),tags$p('Each row is an alternative decision, not guaranteed extra income. Do not add values for overlapping grants, books or mutually exclusive awards. Funding a team is not personal earnings. Winning does not automatically finish preparation tasks, and finishing the goal does not mean an award was won.')))
}
opportunityServer <- function(id,state,commit,open_goal=function(id){})moduleServer(id,function(input,output,session){
 editing<-reactiveVal('')
 observe({s<-state();o<-s$opportunities;choices<-choices_id(o,'name');updateSelectInput(session,'selected',choices=choices,selected=if(isolate(editing())%in%o$id)isolate(editing())else isolate(input$selected));current<-isolate(input$compare);if(is.null(current))current<-o$id[o$status%in%c('Considering','Pursuing','Submitted')];updateCheckboxGroupInput(session,'compare',choices=choices,selected=intersect(current,o$id));updateSelectInput(session,'job',choices=choices_id(s$jobs,'name'),selected=isolate(input$job));updateSelectInput(session,'goal_link',choices=choices_id(s$goals,blank=TRUE),selected=if(isolate(editing())%in%o$id)o$goal_id[match(isolate(editing()),o$id)]else isolate(input$goal_link))})
 load<-function(id){o<-state()$opportunities;i<-match(id,o$id);req(!is.na(i));r<-o[i,];editing(id)
 for(k in c('name','notes'))updateTextInput(session,k,value=r[[k]])
 updateTextAreaInput(session,'basis',value=r$basis)
 for(k in c('kind','status'))updateSelectInput(session,k,selected=r[[k]])
 updateSelectInput(session,'job',selected=r$job_id);updateSelectInput(session,'goal_link',selected=r$goal_id);updateDateInput(session,'deadline',value=r$deadline)
 for(k in c('hours','income_success','income_failure','cost_upfront','cost_success','cost_failure','award_total','years'))updateNumericInput(session,k,value=r[[k]])
 for(k in c('low','base','high'))updateNumericInput(session,k,value=100*r[[paste0('p_',k)]])
 updateNumericInput(session,'discount',value=100*r$discount);updateNumericInput(session,'alt',value=r$alt_hour);updateTextInput(session,'group',value=r$exclusive_group)
 }
 observeEvent(input$load,load(input$selected))
 observeEvent(input$new,{editing('');updateTextInput(session,'name',value='');updateSelectInput(session,'goal_link',selected='');updateSelectInput(session,'status',selected='Considering')})
 observeEvent(input$save,{tryCatch({s<-state();id<-editing();if(!nzchar(id))id<-next_id('o',record_ids(s,'opportunities'));r<-new_opportunity(id,input$job,trimws(input$name),input$deadline,input$kind);r$status<-input$status
  for(k in c('hours','income_success','income_failure','cost_upfront','cost_success','cost_failure','award_total','years'))r[[k]]<-input[[k]]
  for(k in c('low','base','high'))r[[paste0('p_',k)]]<-input[[k]]/100
  r$discount<-input$discount/100;r$alt_hour<-input$alt;r$exclusive_group<-input$group %||% '';r$basis<-input$basis %||% '';r$notes<-input$notes %||% '';r$goal_id<-input$goal_link %||% ''
  if(id%in%s$opportunities$id)s$opportunities[match(id,s$opportunities$id),]<-r else s$opportunities<-rbind(s$opportunities,r)
  commit(s);editing(id);updateSelectInput(session,'selected',selected=id);updateCheckboxGroupInput(session,'compare',selected=union(input$compare,id))
 },error=notify_error)})
 report<-reactive({if(!length(input$compare))return(data.frame());r<-opportunity_report(state(),input$compare);if(!nrow(r))return(r);key<-switch(input$sort %||% 'Expected economic value per hour','Conservative economic value'='Conservative_value','Chance of success'='Chance_pct','Expected cash'='Expected_cash','Smallest cash loss'='Maximum_cash_loss','Economic_value_per_h');r[order(r[[key]],decreasing=key!='Maximum_cash_loss',na.last=TRUE),,drop=FALSE]})
 output$comparison<-renderTable({r<-report();if(!nrow(r))return(NULL);d<-r[,c('Opportunity','Role','Chance_pct','Remaining_h','Personal_income_if_successful','Expected_cash','Economic_value_per_h','Maximum_cash_loss','Deadline')];names(d)<-c('Opportunity','Work role','Success (%)','Hours left','Personal income if successful','Expected cash (present value)','Economic value / hour','Worst cash loss','Deadline');d},digits=2,striped=TRUE,na='Not applicable')
 output$details<-renderTable({r<-report();if(!nrow(r))return(NULL);r[,c('Opportunity','Status','Logged_h','Economic_value','Conservative_value','Optimistic_value','Cash_loss_chance_pct','Break_even_chance_pct','Goal','Exclusive_group')]},digits=2,striped=TRUE,na='Not applicable')
 output$tradeoffs<-renderUI({r<-report();if(!nrow(r))return(tags$p(class='empty-hint','Add opportunities, then select at least two to compare the trade-offs.'));tagList(tags$p(paste(nrow(r),'options selected. Cash and economic values are in',state()$settings$currency,'before tax.')),if(anyDuplicated(r$Exclusive_group[nzchar(r$Exclusive_group)]))tags$div(class='notice warning','Some selected options overlap or are mutually exclusive. Compare their rows; do not sum the potential income.'),if(any(r$Economic_value<0))tags$p('Some options have negative central economic value. Personal meaning, obligations or team benefits may still matter; they are not priced here.'),tags$p(class='hint','Compare return, chances, worst cash exposure and effort together. The chosen sort does not automatically reorder your tasks.'))})
 output$risk_plot<-renderPlot({r<-report();par(mar=c(5,5,2,1),bg=design_tokens$surface);if(!nrow(r)){plot.new();text(.5,.5,'Your opportunities will appear here.',col=design_tokens$muted);return()};plot(r$Maximum_cash_loss,r$Economic_value,xlab='Worst entered cash loss',ylab='Central economic value',pch=21,bg=design_tokens$lavender,col=design_tokens$ink,cex=1.6,xlim=c(0,max(1,r$Maximum_cash_loss)*1.2),ylim=range(c(0,r$Economic_value))+c(-1,1)*max(1,diff(range(c(0,r$Economic_value))))*.18);abline(h=0,lty=2,col=design_tokens$muted);text(r$Maximum_cash_loss,r$Economic_value,labels=substr(r$Opportunity,1,28),pos=3,cex=.75,col=design_tokens$ink)},res=110)
 output$connection<-renderUI({s<-state();i<-match(input$selected %||% '',s$opportunities$id);if(length(i)!=1||is.na(i))return(tags$p(class='hint','Save an opportunity before turning it into a goal.'));o<-s$opportunities[i,];e<-opportunity_effort(s,o);tags$p(class='hint',paste(e$actual,'hours logged ·',e$remaining,'hours still forecast.',if(nzchar(o$goal_id))'Open the linked goal to adjust it or manage its tasks in Today.'else'Create a goal to add a preparation task to Today; both remain editable.'))})
 observeEvent(input$goal,{tryCatch({r<-create_opportunity_goal(state(),input$selected);if(!identical(r$state,state()))commit(r$state);open_goal(r$goal_id)},error=notify_error)})
 observeEvent(input$delete,{req(input$selected);session$userData$remove_opportunity<-input$selected;showModal(modalDialog(title='Delete this opportunity?',tags$p('It leaves the comparison and stays in backup history. Linked goals, tasks and actual time stay intact.'),footer=tagList(modalButton('Cancel'),actionButton(session$ns('delete_confirm'),'Delete opportunity',class='btn-danger'))))})
 observeEvent(input$delete_confirm,{s<-append_archive(state(),'opportunities',session$userData$remove_opportunity);tryCatch({commit(s);editing('');removeModal()},error=notify_error)})
 output$csv<-downloadHandler(filename='opportunity-comparison.csv',content=function(file)write.csv(report(),file,row.names=FALSE,na='',fileEncoding='UTF-8'))
 list(report=report,editing=editing)
})
